const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
let currentLanguage = "en";

const frameImage = document.querySelector("#hero-frame");
const figureButton = document.querySelector(".hero-figure");
const frameUrls = Array.from({ length: 6 }, (_, index) => `assets/anni-frame-${index}.png?v=4`);
let frameTimer = null;

frameUrls.forEach((url) => {
  const image = new Image();
  image.src = url;
});

function playCharacterAnimation() {
  if (frameTimer) window.clearInterval(frameTimer);
  if (reduceMotion.matches) {
    frameImage.src = frameUrls.at(-1);
    return;
  }

  let frame = 0;
  frameImage.src = frameUrls[frame];
  frameTimer = window.setInterval(() => {
    frame += 1;
    frameImage.src = frameUrls[frame];
    if (frame === frameUrls.length - 1) {
      window.clearInterval(frameTimer);
      frameTimer = null;
    }
  }, 130);
}

figureButton.addEventListener("pointerenter", (event) => {
  if (event.pointerType !== "touch") playCharacterAnimation();
});
figureButton.addEventListener("click", playCharacterAnimation);

const heroLettering = document.querySelector(".hero-lettering");
const heroLetters = [...document.querySelectorAll(".hero-letter")];
let heroLetterCenters = [];

function resetHeroLetters() {
  heroLetters.forEach((letter) => {
    letter.style.setProperty("--letter-scale", "1");
    letter.style.setProperty("--letter-lift", "0px");
    letter.style.setProperty("--letter-space", "0px");
    letter.style.zIndex = "1";
  });
}

heroLettering.addEventListener("pointerenter", (event) => {
  if (event.pointerType === "touch" || reduceMotion.matches) return;
  resetHeroLetters();
  heroLetterCenters = heroLetters.map((letter) => {
    const rect = letter.getBoundingClientRect();
    return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, width: rect.width };
  });
});
heroLettering.addEventListener("pointermove", (event) => {
  if (event.pointerType === "touch" || reduceMotion.matches) return;
  heroLetters.forEach((letter, index) => {
    const center = heroLetterCenters[index];
    if (!center) return;
    const distance = Math.hypot(event.clientX - center.x, event.clientY - center.y);
    const proximity = Math.max(0, 1 - distance / 104);
    const eased = proximity * proximity * (3 - 2 * proximity);
    const scale = 1 + eased * 0.36;
    const extraSpace = (scale - 1) * center.width * 0.65;
    const direction = letter.closest(".hero-lettering__row--bottom") ? 1 : -1;
    letter.style.setProperty("--letter-scale", scale.toFixed(3));
    letter.style.setProperty("--letter-lift", `${(direction * eased * 8).toFixed(1)}px`);
    letter.style.setProperty("--letter-space", `${extraSpace.toFixed(1)}px`);
    letter.style.zIndex = String(2 + Math.round(eased * 8));
  });
});
heroLettering.addEventListener("pointerleave", () => {
  heroLetterCenters = [];
  resetHeroLetters();
});

