const nextPageButton = document.querySelector(".book-control--next");
let currentLifeCategory = "timer";
let currentBookLeaf = 0;
let currentBookMaxTurns = 0;
let pageIsTurning = false;
let bookTransitionTimer = null;

function createBookFace(image, side) {
  const face = document.createElement("figure");
  face.className = `book-sheet__face book-sheet__face--${side}`;
  if (!image) {
    face.classList.add("is-empty");
    return face;
  }

  const element = document.createElement("img");
  element.src = image.src;
  element.alt = image.alt;
  element.loading = "lazy";
  element.draggable = false;
  face.append(element);
  return face;
}

function updateBookControls() {
  const timerSelected = currentLifeCategory === "timer";
  previousPageButton.hidden = timerSelected;
  nextPageButton.hidden = timerSelected;
  previousPageButton.disabled = currentBookLeaf === 0;
  nextPageButton.disabled = currentBookLeaf >= currentBookMaxTurns;
}

function renderLifeBook() {
  const timerSelected = currentLifeCategory === "timer";
  lifeBook.classList.toggle("is-project", timerSelected);
  gallerySpread.hidden = timerSelected;
  timerSpread.hidden = !timerSelected;

  if (timerSelected) {
    renderTimerCalendar();
    updateBookControls();
    return;
  }

  const category = lifeBookData[currentLifeCategory];
  currentBookLeaf = 0;
  currentBookMaxTurns = Math.floor((category.images.length - 1) / 2);
  pageIsTurning = false;
  if (bookTransitionTimer) window.clearTimeout(bookTransitionTimer);
  bookBaseImage.src = category.images[0].src;
  bookBaseImage.alt = category.images[0].alt;
  bookSheets.replaceChildren();

  const pageImages = category.images.slice(1);
  for (let index = 0; index < pageImages.length; index += 2) {
    const sheetIndex = index / 2;
    const sheet = document.createElement("div");
    sheet.className = "book-sheet";
    sheet.dataset.sheetIndex = String(sheetIndex);
    sheet.style.zIndex = String(100 - sheetIndex);
    sheet.append(createBookFace(pageImages[index], "front"), createBookFace(pageImages[index + 1], "back"));
    bookSheets.append(sheet);
  }

  category.images.forEach((imageData) => {
    const preload = new Image();
    preload.src = imageData.src;
  });
  updateBookControls();
}

function selectLifeCategory(category) {
  currentLifeCategory = category;
  lifeTabs.forEach((tab) => {
    const selected = tab.dataset.lifeCategory === category;
    tab.classList.toggle("is-active", selected);
    tab.setAttribute("aria-selected", String(selected));
  });
  renderLifeBook();
}

function turnLifePage(step) {
  if (pageIsTurning || currentLifeCategory === "timer") return;
  const sheets = [...bookSheets.children];
  const nextLeaf = currentBookLeaf + step;
  if (nextLeaf < 0 || nextLeaf > currentBookMaxTurns) return;
  pageIsTurning = true;
  const sheetIndex = step > 0 ? currentBookLeaf : currentBookLeaf - 1;
  const sheet = sheets[sheetIndex];
  sheet.style.zIndex = String(300 + sheetIndex);
  sheet.classList.toggle("is-flipped", step > 0);
  currentBookLeaf = nextLeaf;
  updateBookControls();

  const finishTurn = () => {
    sheet.style.zIndex = String(step > 0 ? 100 + sheetIndex : 100 - sheetIndex);
    pageIsTurning = false;
  };
  if (reduceMotion.matches) {
    finishTurn();
  } else {
    bookTransitionTimer = window.setTimeout(finishTurn, 780);
  }
}

lifeTabs.forEach((tab) => {
  tab.addEventListener("click", () => selectLifeCategory(tab.dataset.lifeCategory));
});
previousPageButton.addEventListener("click", () => turnLifePage(-1));
nextPageButton.addEventListener("click", () => turnLifePage(1));
gallerySpread.addEventListener("click", (event) => {
  if (event.target.closest("button")) return;
  const rect = gallerySpread.getBoundingClientRect();
  turnLifePage(event.clientX < rect.left + rect.width / 2 ? -1 : 1);
});

function setLanguage(language) {
  currentLanguage = translations[language] ? language : "en";
  const content = translations[currentLanguage];
  document.documentElement.lang = currentLanguage;
  document.title = content.documentTitle;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    if (content[key]) element.textContent = content[key];
  });

  document.querySelectorAll("[data-i18n-html]").forEach((element) => {
    const key = element.dataset.i18nHtml;
    if (content[key]) element.innerHTML = content[key];
  });

  languageButtons.forEach((button) => {
    const active = button.dataset.language === currentLanguage;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });

  const phone = document.querySelector("[data-contact-phone]");
  const chinese = currentLanguage === "zh-CN";
  phone.textContent = chinese ? "+86 15073051689" : "+32 476930753";
  phone.href = chinese ? "tel:+8615073051689" : "tel:+32476930753";

  renderLifeBook();
  updateTimerStatus();
  renderTimerCalendar();
  updateInterfaceLabels();
  try {
    window.localStorage.setItem("anni-language", currentLanguage);
  } catch {
    // Language persistence is optional.
  }
}

languageButtons.forEach((button) => {
  button.addEventListener("click", () => setLanguage(button.dataset.language));
});

function setMenu(open) {
  menuButton.setAttribute("aria-expanded", String(open));
  menu.setAttribute("aria-hidden", String(!open));
  menu.classList.toggle("is-open", open);
  document.body.classList.toggle("menu-open", open);
  updateInterfaceLabels();

  if (open) {
    lastFocusedElement = document.activeElement;
    window.setTimeout(() => languageButtons[0].focus(), 220);
  } else if (lastFocusedElement) {
    lastFocusedElement.focus();
  }
}

menuButton.addEventListener("click", () => {
  setMenu(menuButton.getAttribute("aria-expanded") !== "true");
});
menuLinks.forEach((link) => link.addEventListener("click", () => setMenu(false)));

document.addEventListener("keydown", (event) => {
  const menuIsOpen = menuButton.getAttribute("aria-expanded") === "true";
  if (event.key === "Escape" && menuIsOpen) setMenu(false);
  if (!menuIsOpen && document.activeElement?.closest("[data-life-book]")) {
    if (event.key === "ArrowLeft") turnLifePage(-1);
    if (event.key === "ArrowRight") turnLifePage(1);
  }
  if (event.key !== "Tab" || !menuIsOpen) return;

  const focusable = [menuButton, ...languageButtons, ...menuLinks];
  const first = focusable[0];
  const last = focusable.at(-1);
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus();
  }
});

document.querySelectorAll("[data-expand-panel]").forEach((panel) => {
  const trigger = panel.querySelector(".expand-panel__trigger");
  let openedByHover = false;

  const setOpen = (open) => {
    panel.classList.toggle("is-open", open);
    trigger.setAttribute("aria-expanded", String(open));
  };

  trigger.addEventListener("pointerenter", (event) => {
    if (event.pointerType === "touch") return;
    openedByHover = true;
    setOpen(true);
  });
  panel.addEventListener("pointerleave", (event) => {
    if (event.pointerType === "touch") return;
    openedByHover = false;
    setOpen(false);
  });
  trigger.addEventListener("click", () => {
    if (openedByHover) {
      setOpen(true);
      return;
    }
    setOpen(trigger.getAttribute("aria-expanded") !== "true");
  });
  panel.addEventListener("focusout", (event) => {
    if (!panel.contains(event.relatedTarget)) setOpen(false);
  });
});

document.querySelectorAll("[data-gallery]").forEach((gallery) => {
  const track = gallery.querySelector(".gallery__track");
  const slides = [...gallery.querySelectorAll(".gallery__slide")];
  const previousButton = gallery.querySelector(".gallery__button--previous");
  const nextButton = gallery.querySelector(".gallery__button--next");
  if (slides.length < 2) {
    previousButton.hidden = true;
    nextButton.hidden = true;
    return;
  }

  track.prepend(slides.at(-1).cloneNode(true));
  track.append(slides[0].cloneNode(true));
  let position = 1;
  let transitioning = false;
  let wheelReady = true;

  const setPosition = (animated) => {
    track.style.transition = animated ? "" : "none";
    track.style.transform = `translateX(-${position * 100}%)`;
    if (!animated) {
      track.getBoundingClientRect();
      track.style.transition = "";
    }
  };

  const move = (step) => {
    if (transitioning) return;
    transitioning = true;
    position += step;
    setPosition(true);
  };

  setPosition(false);
  track.addEventListener("transitionend", (event) => {
    if (event.propertyName !== "transform") return;
    if (position === 0) {
      position = slides.length;
      setPosition(false);
    } else if (position === slides.length + 1) {
      position = 1;
      setPosition(false);
    }
    transitioning = false;
  });

  previousButton.addEventListener("click", () => move(-1));
  nextButton.addEventListener("click", () => move(1));
  gallery.addEventListener(
    "wheel",
    (event) => {
      const delta = Math.abs(event.deltaY) >= Math.abs(event.deltaX) ? event.deltaY : event.deltaX;
      if (Math.abs(delta) < 8) return;
      event.preventDefault();
      if (!wheelReady) return;
      wheelReady = false;
      move(delta > 0 ? 1 : -1);
      window.setTimeout(() => {
        wheelReady = true;
      }, 460);
    },
    { passive: false }
  );
});

const timerElements = {
  display: document.querySelector("#timer-display"),
  status: document.querySelector("#timer-status"),
  start: document.querySelector("#timer-start"),
  pause: document.querySelector("#timer-pause"),
  reset: document.querySelector("#timer-reset"),
  ring: document.querySelector("#timer-ring"),
  grid: document.querySelector("#timer-calendar-grid"),
  calendar: document.querySelector(".timer-calendar"),
  calendarMonth: document.querySelector("#calendar-month"),
  calendarYear: document.querySelector("#calendar-year"),
  calendarPrevious: document.querySelector("#calendar-previous"),
  calendarNext: document.querySelector("#calendar-next"),
  calendarSummary: document.querySelector("#calendar-summary"),
  monthView: document.querySelector("#calendar-month-view"),
  yearView: document.querySelector("#calendar-year-view"),
  popup: document.querySelector("#timer-popup"),
  popupImage: document.querySelector("#timer-popup-image"),
  popupTitle: document.querySelector("#timer-popup-title"),
  popupMessage: document.querySelector("#timer-popup-message"),
  popupConfirm: document.querySelector("#timer-popup-confirm"),
};

const timerState = {
  running: false,
  paused: false,
  mode: "focus",
  remaining: 45 * 60,
  focusTotal: 45 * 60,
  breakTotal: 15 * 60,
  interval: null,
  transitionTimeout: null,
  statusKey: "timerReady",
};

const calendarToday = new Date();
const calendarState = {
  year: calendarToday.getFullYear(),
  month: calendarToday.getMonth(),
  mode: "month",
};

function readDuration(prefix) {
  const hours = Number(document.querySelector(`#${prefix}-hours`).value) || 0;
  const minutes = Number(document.querySelector(`#${prefix}-minutes`).value) || 0;
  const seconds = Number(document.querySelector(`#${prefix}-seconds`).value) || 0;
  return Math.max(0, Math.min(23, hours)) * 3600 + Math.max(0, Math.min(59, minutes)) * 60 + Math.max(0, Math.min(59, seconds));
}

function formatDuration(seconds) {
  const safeSeconds = Math.max(0, seconds);
  const hours = Math.floor(safeSeconds / 3600);
  const minutes = Math.floor((safeSeconds % 3600) / 60);
  const secs = safeSeconds % 60;
  return [hours, minutes, secs].map((value) => String(value).padStart(2, "0")).join(":");
}

function updateTimerDisplay() {
  timerElements.display.textContent = formatDuration(timerState.remaining);
}

function updateTimerStatus() {
  const content = translations[currentLanguage];
  timerElements.status.textContent = content[timerState.statusKey];
  timerElements.pause.textContent = content[timerState.paused ? "timerResume" : "timerPause"];
}

function playRing() {
  timerElements.ring.currentTime = 0;
  timerElements.ring.play().catch(() => {});
}

function localDateKey(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function loadTimerRecords() {
  try {
    return JSON.parse(window.localStorage.getItem("anni-timer-records") || "{}");
  } catch {
    return {};
  }
}

function saveFocusRecord(seconds) {
  const records = loadTimerRecords();
  const key = localDateKey();
  records[key] = (records[key] || 0) + seconds;
  try {
    window.localStorage.setItem("anni-timer-records", JSON.stringify(records));
  } catch {
    // The timer remains usable when storage is unavailable.
  }
}

function updateCalendarNavigationLabels() {
  if (!timerElements?.calendarPrevious) return;
  const labels = interfaceText[currentLanguage];
  const yearMode = calendarState.mode === "year";
  timerElements.calendarPrevious.setAttribute("aria-label", yearMode ? labels.previousYear : labels.previousMonth);
  timerElements.calendarPrevious.title = yearMode ? labels.previousYear : labels.previousMonth;
  timerElements.calendarNext.setAttribute("aria-label", yearMode ? labels.nextYear : labels.nextMonth);
  timerElements.calendarNext.title = yearMode ? labels.nextYear : labels.nextMonth;
}

function appendCalendarBlank(grid, className) {
  const blank = document.createElement("span");
  blank.className = className;
  blank.setAttribute("aria-hidden", "true");
  grid.append(blank);
}

function formatFocusTime(seconds) {
  if (seconds <= 0) return "";
  const totalMinutes = Math.max(1, Math.round(seconds / 60));
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (currentLanguage === "zh-CN") {
    if (hours && minutes) return `${hours}时${minutes}分`;
    if (hours) return `${hours}时`;
    return `${minutes}分`;
  }
  if (hours && minutes) return `${hours}h${minutes}m`;
  if (hours) return `${hours}h`;
  return `${minutes}m`;
}

function renderMonthCalendar(records) {
  const firstDay = new Date(calendarState.year, calendarState.month, 1);
  const daysInMonth = new Date(calendarState.year, calendarState.month + 1, 0).getDate();
  const mondayOffset = (firstDay.getDay() + 6) % 7;
  const weekCount = Math.ceil((mondayOffset + daysInMonth) / 7);
  timerElements.grid.replaceChildren();

  for (let week = 0; week < weekCount; week += 1) {
    let weekSeconds = 0;
    for (let column = 0; column < 7; column += 1) {
      const day = week * 7 + column - mondayOffset + 1;
      if (day < 1 || day > daysInMonth) {
        appendCalendarBlank(timerElements.grid, "calendar-day");
        continue;
      }

      const date = new Date(calendarState.year, calendarState.month, day);
      const seconds = records[localDateKey(date)] || 0;
      const cell = document.createElement("span");
      const dayNumber = document.createElement("span");
      const focusTime = document.createElement("span");
      weekSeconds += seconds;
      cell.className = "calendar-day";
      if (
        calendarState.year === calendarToday.getFullYear() &&
        calendarState.month === calendarToday.getMonth() &&
        day === calendarToday.getDate()
      ) {
        cell.classList.add("is-today");
      }
      dayNumber.textContent = String(day);
      focusTime.className = "calendar-day__time";
      focusTime.textContent = formatFocusTime(seconds);
      cell.append(dayNumber, focusTime);
      timerElements.grid.append(cell);
    }

    const weekTotal = document.createElement("span");
    const weekText = formatFocusTime(weekSeconds);
    weekTotal.className = "calendar-week-total";
    weekTotal.textContent = weekText;
    if (weekText) {
      weekTotal.setAttribute("aria-label", currentLanguage === "zh-CN" ? `本周专注 ${weekText}` : `This week: ${weekText} focused`);
    } else {
      weekTotal.setAttribute("aria-hidden", "true");
    }
    timerElements.grid.append(weekTotal);
  }
}

function renderYearCalendar(records, locale) {
  timerElements.yearView.replaceChildren();
  for (let month = 0; month < 12; month += 1) {
    const monthSection = document.createElement("section");
    const monthButton = document.createElement("button");
    const monthGrid = document.createElement("div");
    const firstDay = new Date(calendarState.year, month, 1);
    const daysInMonth = new Date(calendarState.year, month + 1, 0).getDate();
    const mondayOffset = (firstDay.getDay() + 6) % 7;
    monthSection.className = "mini-month";
    monthButton.className = "mini-month__title";
    monthButton.type = "button";
    monthButton.textContent = new Intl.DateTimeFormat(locale, { month: "short" }).format(firstDay);
    monthButton.addEventListener("click", () => {
      calendarState.month = month;
      calendarState.mode = "month";
      renderTimerCalendar();
    });
    monthGrid.className = "mini-month__grid";
    for (let index = 0; index < mondayOffset; index += 1) appendCalendarBlank(monthGrid, "mini-calendar-day");
    for (let day = 1; day <= daysInMonth; day += 1) {
      const date = new Date(calendarState.year, month, day);
      const cell = document.createElement("span");
      cell.className = "mini-calendar-day";
      cell.textContent = String(day);
      if (records[localDateKey(date)] > 0) cell.classList.add("has-focus");
      monthGrid.append(cell);
    }
    monthSection.append(monthButton, monthGrid);
    timerElements.yearView.append(monthSection);
  }
}

function renderTimerCalendar() {
  if (!timerElements.grid) return;
  const selectedDate = new Date(calendarState.year, calendarState.month, 1);
  const records = loadTimerRecords();
  const locale = currentLanguage === "zh-CN" ? "zh-CN" : "en-GB";
  const yearMode = calendarState.mode === "year";
  timerElements.calendarMonth.textContent = new Intl.DateTimeFormat(locale, { month: "long" }).format(selectedDate);
  timerElements.calendarYear.textContent = String(calendarState.year);
  timerElements.calendar.classList.toggle("is-year-view", yearMode);
  timerElements.monthView.hidden = yearMode;
  timerElements.yearView.hidden = !yearMode;
  timerElements.calendarSummary.hidden = !yearMode;
  const focusedDays = Object.values(records).filter((seconds) => Number(seconds) > 0).length;
  const dayUnit = focusedDays === 1 ? translations[currentLanguage].timerDayUnit : translations[currentLanguage].timerDaysUnit;
  timerElements.calendarSummary.textContent = yearMode ? `${focusedDays} ${dayUnit}` : "";

  if (yearMode) renderYearCalendar(records, locale);
  else renderMonthCalendar(records);
  updateCalendarNavigationLabels();
}

function shiftCalendar(step) {
  if (calendarState.mode === "year") {
    calendarState.year += step;
  } else {
    const date = new Date(calendarState.year, calendarState.month + step, 1);
    calendarState.year = date.getFullYear();
    calendarState.month = date.getMonth();
  }
  renderTimerCalendar();
}

timerElements.calendarMonth.addEventListener("click", () => {
  calendarState.mode = "month";
  renderTimerCalendar();
});
timerElements.calendarYear.addEventListener("click", () => {
  calendarState.mode = "year";
  renderTimerCalendar();
});
timerElements.calendarPrevious.addEventListener("click", () => shiftCalendar(-1));
timerElements.calendarNext.addEventListener("click", () => shiftCalendar(1));

let timerPopupCallback = null;

function openTimerPopup(kind, callback) {
  const content = translations[currentLanguage];
  const focusDone = kind === "focus";
  timerElements.popup.dataset.kind = kind;
  timerElements.popupImage.src = focusDone ? "assets/timer-focus.png?v=4" : "assets/timer-break.png?v=4";
  timerElements.popupImage.alt = "";
  timerElements.popupTitle.textContent = content[focusDone ? "timerFocusPopupTitle" : "timerBreakPopupTitle"];
  timerElements.popupMessage.textContent = content[focusDone ? "timerFocusPopupMessage" : "timerBreakPopupMessage"];
  timerElements.popupConfirm.textContent = content.timerPopupConfirm;
  timerPopupCallback = callback;
  if (typeof timerElements.popup.showModal === "function") timerElements.popup.showModal();
  else timerElements.popup.setAttribute("open", "");
}

function confirmTimerPopup() {
  const callback = timerPopupCallback;
  timerPopupCallback = null;
  if (typeof timerElements.popup.close === "function") timerElements.popup.close();
  else timerElements.popup.removeAttribute("open");
  if (callback) window.setTimeout(callback, 0);
}

timerElements.popupConfirm.addEventListener("click", confirmTimerPopup);
timerElements.popup.addEventListener("cancel", (event) => {
  event.preventDefault();
  confirmTimerPopup();
});

function clearTimerInterval() {
  if (timerState.interval) window.clearInterval(timerState.interval);
  if (timerState.transitionTimeout) window.clearTimeout(timerState.transitionTimeout);
  timerState.interval = null;
  timerState.transitionTimeout = null;
}

function finishTimerStage() {
  clearTimerInterval();
  playRing();
  if (timerState.mode === "focus") {
    saveFocusRecord(timerState.focusTotal);
    renderTimerCalendar();
    timerState.running = false;
    timerState.statusKey = "timerFocusDone";
    updateTimerStatus();
    openTimerPopup("focus", () => {
      timerState.mode = "break";
      timerState.remaining = timerState.breakTotal;
      timerState.statusKey = "timerBreakStatus";
      updateTimerDisplay();
      updateTimerStatus();
      if (timerState.breakTotal > 0) runTimerInterval();
      else finishTimerStage();
    });
  } else {
    timerState.running = false;
    timerState.statusKey = "timerBreakDone";
    updateTimerStatus();
    openTimerPopup("break", resetTimer);
  }
}

function runTimerInterval() {
  timerState.running = true;
  timerState.paused = false;
  clearTimerInterval();
  timerState.interval = window.setInterval(() => {
    if (timerState.paused) return;
    timerState.remaining -= 1;
    updateTimerDisplay();
    if (timerState.remaining <= 0) finishTimerStage();
  }, 1000);
}

function startTimer() {
  if (timerState.running) return;
  timerState.focusTotal = readDuration("focus");
  timerState.breakTotal = readDuration("break");
  if (timerState.focusTotal <= 0) return;
  timerState.mode = "focus";
  timerState.remaining = timerState.focusTotal;
  timerState.statusKey = "timerFocusing";
  updateTimerDisplay();
  updateTimerStatus();
  runTimerInterval();
}

function pauseTimer() {
  if (!timerState.running) return;
  timerState.paused = !timerState.paused;
  timerState.statusKey = timerState.paused ? "timerPaused" : timerState.mode === "focus" ? "timerFocusing" : "timerBreakStatus";
  updateTimerStatus();
}

function resetTimer() {
  clearTimerInterval();
  timerState.running = false;
  timerState.paused = false;
  timerState.mode = "focus";
  timerState.focusTotal = readDuration("focus") || 45 * 60;
  timerState.breakTotal = readDuration("break");
  timerState.remaining = timerState.focusTotal;
  timerState.statusKey = "timerReady";
  updateTimerDisplay();
  updateTimerStatus();
}

timerElements.start.addEventListener("click", startTimer);
timerElements.pause.addEventListener("click", pauseTimer);
timerElements.reset.addEventListener("click", resetTimer);
document.querySelectorAll(".timer-inputs input").forEach((input) => {
  input.addEventListener("change", () => {
    const min = Number(input.min);
    const max = Number(input.max);
    input.value = String(Math.max(min, Math.min(max, Number(input.value) || 0))).padStart(2, "0");
    if (!timerState.running) resetTimer();
  });
});

const revealElements = document.querySelectorAll(".reveal");
if (reduceMotion.matches || !("IntersectionObserver" in window)) {
  revealElements.forEach((element) => element.classList.add("is-visible"));
} else {
  const revealObserver = new IntersectionObserver(
    (entries, observer) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add("is-visible");
        observer.unobserve(entry.target);
      });
    },
    { threshold: 0.1 }
  );
  revealElements.forEach((element) => revealObserver.observe(element));
}

let savedLanguage = "en";
try {
  savedLanguage = window.localStorage.getItem("anni-language") || "en";
} catch {
  savedLanguage = "en";
}
renderTimerCalendar();
updateTimerDisplay();
setLanguage(savedLanguage);
